const input = $input.first().json;
const required = ['tenantId','providerPhoneNumberId','to','text','traceId','businessActionId','idempotencyKey'];
const missing = required.filter((k) => input[k] === undefined || input[k] === null || input[k] === '');
if (missing.length) throw new Error(`KAPSO_SEND_INVALID_INPUT missing=${missing.join(',')}`);
const text = String(input.text);
if (!text.length || text.length > 4096) throw new Error('KAPSO_SEND_TEXT_LENGTH_INVALID');
const to = String(input.to).replace(/[^0-9]/g, '');
if (!to) throw new Error('KAPSO_SEND_RECIPIENT_INVALID');
const businessActionId = String(input.businessActionId);
if (businessActionId.length > 512) throw new Error('KAPSO_SEND_BUSINESS_ACTION_ID_TOO_LONG');
return [{ json: {
  tenantId: String(input.tenantId),
  provider: 'kapso',
  providerPhoneNumberId: String(input.providerPhoneNumberId),
  to,
  text,
  traceId: String(input.traceId),
  businessActionId,
  idempotencyKey: String(input.idempotencyKey),
  payload: {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to,
    type: 'text',
    biz_opaque_callback_data: businessActionId,
    text: { body: text, preview_url: false }
  }
} }];

const request = $('Validate Send Request').first().json;
const response = $input.first().json || {};
const providerMessageId = response.messages?.[0]?.id ? String(response.messages[0].id) : '';
if (!providerMessageId) throw new Error('KAPSO_SEND_PROVIDER_MESSAGE_ID_MISSING');
const waId = response.contacts?.[0]?.wa_id ? String(response.contacts[0].wa_id) : request.to;
return [{ json: {
  schemaVersion: '1.0',
  tenantId: request.tenantId,
  provider: 'kapso',
  channel: 'whatsapp',
  providerPhoneNumberId: request.providerPhoneNumberId,
  recipientId: waId,
  providerMessageId,
  businessActionId: request.businessActionId,
  idempotencyKey: request.idempotencyKey,
  traceId: request.traceId,
  status: 'accepted_by_provider',
  retrySafe: false
} }];
